import{_ as s,o as t,c as i,a4 as a}from"./chunks/framework.CmuCl-jw.js";const k=JSON.parse('{"title":"Access from Other Computers","description":"","frontmatter":{},"headers":[],"relativePath":"local/lan-access.md","filePath":"local/lan-access.md"}'),o={name:"local/lan-access.md"};function n(r,e,l,h,d,c){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="access-from-other-computers" tabindex="-1">Access from Other Computers <a class="header-anchor" href="#access-from-other-computers" aria-label="Permalink to “Access from Other Computers”">​</a></h1><p>Arcsecond.local is multi-user by design, but a fresh installation is only reachable from the machine it runs on, at <code>http://localhost:5555</code>. This page covers what to change so that everyone in the observatory can open it from their own computer, over the local network.</p><p>Everything below is done through graphical interfaces, except one line to add to a configuration file. No new software is needed.</p><p>Throughout this page:</p><ul><li><code>192.168.1.42</code> stands for the IP address of the <strong>machine running Arcsecond.local</strong> (the one running Docker).</li><li><code>5555</code> is the port Arcsecond.local is served on. Leave it as it is.</li></ul><p>Replace the address with your own.</p><h2 id="what-the-other-computers-will-use" tabindex="-1">What the other computers will use <a class="header-anchor" href="#what-the-other-computers-will-use" aria-label="Permalink to “What the other computers will use”">​</a></h2><p>Everyone opens the same page, at the address of the machine running Arcsecond.local:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://192.168.1.42:5555</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p><code>http://localhost:5555</code> only works on the machine running Arcsecond.local. On any other computer, <code>localhost</code> means <em>that</em> computer, so the page never loads. This is the single most common cause of &quot;it works on the observatory PC but nowhere else&quot;.</p></div><p>Only that one port has to be reachable. The API is served from the very same address, under <code>/api/</code>, so there is no second port to open for the web interface.</p><h2 id="_1-note-the-ip-address-of-the-machine" tabindex="-1">1. Note the IP address of the machine <a class="header-anchor" href="#_1-note-the-ip-address-of-the-machine" aria-label="Permalink to “1. Note the IP address of the machine”">​</a></h2><p>On the <strong>machine running Arcsecond.local</strong>:</p><ol><li>Open <strong>Settings → Network &amp; Internet</strong>.</li><li>Click <strong>Wi-Fi</strong> or <strong>Ethernet</strong>, depending on how the machine is connected.</li><li>Click the name of the network, then scroll down to <strong>IPv4 address</strong>.</li><li>Write that address down (e.g. <code>192.168.1.42</code>).</li></ol><h2 id="_2-fix-that-ip-address" tabindex="-1">2. Fix that IP address <a class="header-anchor" href="#_2-fix-that-ip-address" aria-label="Permalink to “2. Fix that IP address”">​</a></h2><p>An address handed out by the router can change after a reboot, and everyone&#39;s bookmark would break with it. Pin it:</p><ol><li>On the same page, next to <strong>IP assignment</strong>, click <strong>Edit</strong>.</li><li>Choose <strong>Manual</strong> in the drop-down.</li><li>Turn <strong>IPv4</strong> on.</li><li>Fill in: <ul><li><strong>IP address</strong>: the address noted at step 1.</li><li><strong>Subnet mask</strong>: <code>255.255.255.0</code>.</li><li><strong>Gateway</strong>: your router&#39;s address (usually the same address ending in <code>.1</code>, e.g. <code>192.168.1.1</code>).</li><li><strong>Preferred DNS</strong>: your router&#39;s address, or <code>1.1.1.1</code>.</li></ul></li><li>Click <strong>Save</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>If your router offers a &quot;DHCP reservation&quot; page, reserving the address there works just as well, and leaves the Windows settings untouched.</p></div><h2 id="_3-set-the-network-profile-to-private" tabindex="-1">3. Set the network profile to Private <a class="header-anchor" href="#_3-set-the-network-profile-to-private" aria-label="Permalink to “3. Set the network profile to Private”">​</a></h2><p>Windows blocks incoming connections much more aggressively on networks marked <em>Public</em>.</p><ol><li>Open <strong>Settings → Network &amp; Internet</strong>.</li><li>Click <strong>Wi-Fi</strong> or <strong>Ethernet</strong>, then the network name.</li><li>Under <strong>Network profile type</strong>, select <strong>Private network</strong>.</li></ol><h2 id="_4-open-the-port-in-the-windows-firewall" tabindex="-1">4. Open the port in the Windows firewall <a class="header-anchor" href="#_4-open-the-port-in-the-windows-firewall" aria-label="Permalink to “4. Open the port in the Windows firewall”">​</a></h2><ol><li>Press the <strong>Windows key</strong>, type <em>firewall</em>, and open <strong>Windows Defender Firewall with Advanced Security</strong>.</li><li>In the left column, click <strong>Inbound Rules</strong>.</li><li>In the right column, click <strong>New Rule…</strong>.</li><li>Select <strong>Port</strong>, click <strong>Next</strong>.</li><li>Select <strong>TCP</strong>, then <strong>Specific local ports</strong>, and type <code>5555</code>. Click <strong>Next</strong>.</li><li>Select <strong>Allow the connection</strong>. Click <strong>Next</strong>.</li><li>Tick <strong>Private</strong> only (untick <strong>Domain</strong> and <strong>Public</strong>). Click <strong>Next</strong>.</li><li><strong>Name</strong>: <code>Arcsecond.local (TCP 5555)</code>. Click <strong>Finish</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>The same rule, in one PowerShell command run as Administrator:</p><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">New-NetFirewallRule</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DisplayName </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Arcsecond.local (TCP 5555)&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Direction Inbound </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Protocol TCP </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LocalPort </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5555</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Profile Private </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Action Allow</span></span></code></pre></div></div><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>If a third-party security suite is installed (Norton, Kaspersky, Bitdefender, ESET…), it has its own firewall. Open its interface and allow the same port there too.</p></div><h2 id="_5-tell-arcsecond-its-own-address" tabindex="-1">5. Tell Arcsecond its own address <a class="header-anchor" href="#_5-tell-arcsecond-its-own-address" aria-label="Permalink to “5. Tell Arcsecond its own address”">​</a></h2><p>Browsing works after step 4. This step is about the links Arcsecond <em>writes</em> — the invitation links you send to new members, and password-reset emails. Those are composed by the server, which has no way of knowing which address people reach it at, so it has to be told. Left unset, every one of those links says <code>localhost</code>, and lands whoever clicks it on their own computer.</p><ol><li><p>Open the <code>.env</code> file sitting next to your <code>docker-compose.yml</code>, in a text editor.</p></li><li><p>Add this line at the end, with your own address:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HOSTED_FRONTEND_HOST=192.168.1.42:5555</span></span></code></pre></div></li><li><p>Save the file.</p></li><li><p>In the Arcsecond folder, apply it:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div></li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>If the change does not seem to take effect, force the containers that read the file to be recreated:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force-recreate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> beat</span></span></code></pre></div></div><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Adding a member does not require email at all: in the invitations panel, the <strong>&quot;Add member with password…&quot;</strong> button creates the account and lets you hand the credentials over directly. Useful on an observatory network with no mail server.</p></div><h2 id="_6-check-from-another-computer" tabindex="-1">6. Check from another computer <a class="header-anchor" href="#_6-check-from-another-computer" aria-label="Permalink to “6. Check from another computer”">​</a></h2><p>On a <strong>different computer on the same network</strong>, open a browser and go to:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://192.168.1.42:5555</span></span></code></pre></div><p>The Arcsecond login page should appear, and you should be able to log in and use the apps exactly as on the observatory machine.</p><p>If the page does not load at all, the request is not reaching the machine: go back through steps 3 and 4. If the page loads but stays empty, or the interface appears and then reports errors, see <a href="#troubleshooting">Troubleshooting</a> below.</p><h2 id="using-a-name-instead-of-an-address" tabindex="-1">Using a name instead of an address <a class="header-anchor" href="#using-a-name-instead-of-an-address" aria-label="Permalink to “Using a name instead of an address”">​</a></h2><p>Typing an IP address is unpleasant to share. Two options:</p><ul><li><strong>An mDNS name.</strong> If the machine is named <code>arcsecond</code>, many networks resolve <code>http://arcsecond.local:5555</code> on their own, with nothing to configure. macOS and Linux handle it out of the box, and recent Windows versions usually do too. If a particular computer cannot resolve the name, installing Bonjour on it (it ships with iTunes) generally settles it — but test it before handing the name around, as support varies between machines and networks.</li><li><strong>A DNS entry on your router.</strong> Many routers let you map a name to a fixed address. This works for every device on the network with nothing to install.</li></ul><p>Either way, add the same name to the <code>.env</code> file at step 5 (for example <code>HOSTED_FRONTEND_HOST=arcsecond.local:5555</code>) so that the links in emails use it too.</p><h2 id="using-the-cli-or-the-api-from-another-computer" tabindex="-1">Using the CLI or the API from another computer <a class="header-anchor" href="#using-the-cli-or-the-api-from-another-computer" aria-label="Permalink to “Using the CLI or the API from another computer”">​</a></h2><p>The web interface only needs port <code>5555</code>. The <a href="/cli/">command-line interface</a> and any script talking to the API directly use port <code>8800</code> instead, which is <strong>not</strong> open by default on the network.</p><p>If you need that, repeat step 4 for port <code>8800</code>, then give the CLI a name for your installation. In <code>~/.config/arcsecond/config.ini</code> (see <a href="/cli/install">Install &amp; Login</a>), add:</p><div class="language-ini"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[local]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">api_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = http://192.168.1.42:8800</span></span></code></pre></div><p>and pass that name to every command:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --username</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">yo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">u</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> access</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">access-ke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Leave the port closed if nobody needs it — the web interface does not.</p><h2 id="if-arcsecond-local-runs-on-macos-or-linux" tabindex="-1">If Arcsecond.local runs on macOS or Linux <a class="header-anchor" href="#if-arcsecond-local-runs-on-macos-or-linux" aria-label="Permalink to “If Arcsecond.local runs on macOS or Linux”">​</a></h2><p>The same five steps apply, with different tools:</p><ul><li><strong>Find the address</strong>: <code>ipconfig getifaddr en0</code> on macOS, <code>ip -4 addr show</code> on Linux.</li><li><strong>Fix the address</strong>: easiest through a DHCP reservation on the router.</li><li><strong>Firewall</strong>: macOS does not block Docker&#39;s published ports by default. On Linux with <code>ufw</code> enabled: <code>sudo ufw allow from 192.168.1.0/24 to any port 5555 proto tcp</code>.</li><li>Steps 5 and 6 are identical.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><p><strong>The page loads but stays blank, or the interface reports it cannot reach the server.</strong> Your installation predates the change that serves the API from the same address as the web interface. Update it, and try again:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p><strong>It works from the observatory machine but nowhere else.</strong> Check that you are using the IP address and not <code>localhost</code> on the other computer, then re-check the firewall rule (step 4) and the network profile (step 3).</p><p><strong>It worked, and stopped after a reboot.</strong> The machine&#39;s IP address most likely changed. Redo step 2 to pin it.</p><p><strong>Invitation or password-reset links send people to a page that does not load.</strong> The address in <code>.env</code> is missing or wrong — see step 5. It must be exactly what people type in their browser, port included.</p><h2 id="a-note-on-security" tabindex="-1">A note on security <a class="header-anchor" href="#a-note-on-security" aria-label="Permalink to “A note on security”">​</a></h2><p>This setup is meant for a <strong>trusted local network</strong>: an observatory LAN, behind a router. Traffic is plain HTTP, not encrypted.</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Do not forward these ports on your router, and do not expose them to the internet. If you need to reach your observatory from outside, use a VPN, or put a reverse proxy terminating TLS in front of Arcsecond.local — in which case set both <code>HOSTED_FRONTEND_HOST</code> (to the public name) and <code>HOSTED_FRONTEND_SCHEME=https</code> in the <code>.env</code> file.</p></div>`,58)])])}const g=s(o,[["render",n]]);export{k as __pageData,g as default};
